(function(){
  try {
    var P = ["email","email_mobile","email_address","email_for_newsletter","firstname","first_name","lastname","last_name","fullname","full_name","recipient_name","company","phone","mobilephone","name_of_organization_or_institute","country_dropdown","why_do_you_think_this_event_will_bring_value_to_your_community","address_line1","address_line2","city","state","zip"];
    function clean(u) {
      if (!u) return u;
      try {
        var x = new URL(u);
        var ks = [];
        x.searchParams.forEach(function (v, k) { ks.push(k); });
        var t = false;
        ks.forEach(function (k) {
          if (P.indexOf(k.toLowerCase()) > -1) { x.searchParams.delete(k); t = true; }
        });
        return t ? x.toString() : u;
      } catch (e) { return u; }
    }
    window.__yqCleanUrl = clean;
    var c = clean(location.href);
    if (c !== location.href && window.history && history.replaceState) {
      history.replaceState(history.state, '', c);
    }
  } catch (e) {}
})();

(function(){
  try {
    window.dataLayer = window.dataLayer || [];
    function gtag(){ dataLayer.push(arguments); }
    window.gtag = window.gtag || gtag;

    gtag('js', new Date());

    // Same hostname switch as getGoogleAnalytics4Id(). Resolved here rather
    // than passed in from React because this script runs before hydration,
    // and the values are NEXT_PUBLIC_* (already public in the client bundle).
    var host = location.hostname;
    var ga4 = host === "yaqeeninstitute.ca"
      ? "G-719ZSFK7J7"
      : host === "yaqeeninstitute.org.my"
      ? "G-QEV5THVSSG"
      : "G-ZWEHXT90DE";

    // DATA-1052: never hand a PII-bearing URL to a Google tag.
    //
    // These overrides are passed ONLY when cleaning actually changed the value.
    // gtag stores config-command parameters and applies them to every later
    // event sent to that target for the page's JS lifetime — which, in this
    // SPA, spans every client-side navigation. Nothing re-sends them, so an
    // unconditional page_location would pin GA4 to the landing URL for the
    // whole session and mis-attribute every later event, including purchases
    // and Ads conversions.
    //
    // Passing nothing in the clean case leaves GA4's own per-event URL
    // collection intact. The PII strip script above has already cleaned
    // location.href, so the clean case is the norm and page_location is
    // normally absent. It reappears only if that rewrite failed — where a
    // frozen-but-clean URL beats a leaked one. document.referrer is read-only
    // and cannot be cleaned in place, so a cross-origin PII referrer (a HubSpot
    // landing page) is the one value this layer genuinely has to carry.
    var yqClean = window.__yqCleanUrl || function (u) { return u; };
    function yqPage() {
      var o = {};
      var href = location.href;
      var cleanHref = yqClean(href);
      if (cleanHref !== href) o.page_location = cleanHref;
      var ref = document.referrer;
      if (ref) {
        var cleanRef = yqClean(ref);
        if (cleanRef !== ref) o.page_referrer = cleanRef;
      }
      return o;
    }

    // GRO-189: see the note above. A global set, queued before config so the
    // entry page_view carries it, and still clearable by unsetGaUser().
    var uidMatch = document.cookie.match(/(?:^|; )ga_uid=([^;]*)/);
    var uid = null;
    if (uidMatch) {
      try { uid = decodeURIComponent(uidMatch[1]); } catch (e) {}
    }
    if (uid) gtag('set', { user_id: uid });

    if (ga4) gtag('config', ga4, yqPage());
    gtag('config', "AW-11022294793", yqPage());
    gtag('config', "AW-16447450703", yqPage());
  } catch (e) {}
})();

